// Examples: {"effective":"2024-01-01T00:00:00Z","id":1,"license":"MIT","published":"2023-06-01T00:00:00Z","type":"released","version":"1.0.0"}, {"effective":"2024-01-01T00:00:00Z","id":3,"published":"2023-06-01T00:00:00Z","supportId":"standard","type":"endOfSupport","versions":[{"version":"1.0.0"}]}
